SELECT
id::"varchar" as financing_customer_id,
"dealerId"::"varchar" as dealer_id,
"dealerManager"::"varchar" as dealer_manager_id,
"taxData"::"varchar" as tax_data,
address::"varchar" as address,
"comments"::"varchar" as "comments",
"dealershipName" as dealership_name ,
"referenceCode" as reference_code,
documents::"varchar" as documents,
"createdAt" as created_at,
"updatedAt" as updated_at,
"deletedAt" as deleted_at,
"createdByName" as created_by_name,
"createdById"::"varchar" as created_by_id,
"updatedByName" as updated_by_name,
"updatedById"::"varchar" as updated_by_id,
"deletedByName" as deleted_by_name,
"deletedById"::"varchar" as deleted_by_id,
"riskScore" as risk_score,
"internalId" as internal_id,
email as email,
phone as phone,
country as country_id,
"manualFreezeReason"::"varchar" as manual_freeze_reason,
"manualFreezeComments"::"varchar" as manual_freeze_comments,
"isManualFreeze"::"varchar" as is_manual_freeze,
"firstname"::"varchar" as first_name,
"lastname"::"varchar" as last_name,
"financingStatus"::"varchar" as financial_status,
"deliveryBlocking"::"varchar" as delivery_blocking,
"biddingBlocking"::"varchar" as bidding_blocking,
"checkoutBlocking"::"varchar" as checkout_blocking,
"creditBlocking"::"varchar" as credit_blocking
FROM "fcgFinancing"."public"."customer"
WHERE "updatedAt" >= '{{params.start_ts}}' AND "updatedAt" < '{{params.end_ts}}'